import CEMETERY_LEVEL from "../assets/data/levels/cemetery/cemetery.json";
import CEMETERY_BACKGROUND from "../assets/data/levels/cemetery/cemetery_background.png";
import CEMETERY_FOREGROUND from "../assets/data/levels/cemetery/cemetery_foreground.png";
import CEMETERY_EVENTS from "../assets/data/levels/cemetery/events.json";
import CEMETERY_NPCS from "../assets/data/levels/cemetery/npcs.json";
import CEMETERY_READABLES from "../assets/data/levels/cemetery/readables.json";
import BAT_JSON from "../assets/images/npcs/cemetery/bat.json";
import BAT_IMG from "../assets/images/npcs/cemetery/bat.png";
import GHOST_JSON from "../assets/images/npcs/cemetery/ghost.json";
import GHOST_IMG from "../assets/images/npcs/cemetery/ghost.png";
import HAND_JSON from "../assets/images/npcs/cemetery/hand.json";
import HAND_IMG from "../assets/images/npcs/cemetery/hand.png";
import MOUSE_JSON from "../assets/images/npcs/cemetery/mouse.json";
import MOUSE_IMG from "../assets/images/npcs/cemetery/mouse.png";
import SLIME_JSON from "../assets/images/npcs/cemetery/slime.json";
import SLIME_IMG from "../assets/images/npcs/cemetery/slime.png";
import CANDLEFLAME_JSON from "../assets/images/world_objects/animated/candleflame.json";
import CANDLEFLAME_IMG from "../assets/images/world_objects/animated/candleflame.png";
import SECRET_DOOR from "../assets/images/world_objects/elder_drifts_secret_door.png";
import REGI_DOOR_JSON from "../assets/images/world_objects/regi_door.json";
import REGI_DOOR_IMG from "../assets/images/world_objects/regi_door.png";
import TRAP_FLAME_JSON from "../assets/images/world_objects/trap_flame.json";
import TRAP_FLAME_IMG from "../assets/images/world_objects/trap_flame.png";
import TRAP_SPIKE_JSON from "../assets/images/world_objects/trap_spike.json";
import TRAP_SPIKE_IMG from "../assets/images/world_objects/trap_spike.png";
import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class ElderDriftsPreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.ELDER_DRIFTS_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadElderDriftsAssets();
  }

  #loadElderDriftsAssets(): void {
    // Load cemetery level assets
    this.load.image(ASSET_KEYS.CEMETERY_BACKGROUND, CEMETERY_BACKGROUND);
    this.load.image(ASSET_KEYS.CEMETERY_FOREGROUND, CEMETERY_FOREGROUND);
    this.load.tilemapTiledJSON(ASSET_KEYS.CEMETERY_LEVEL, CEMETERY_LEVEL);

    // Load cemetery events
    this.load.json(ASSET_KEYS.EVENTS, CEMETERY_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, CEMETERY_NPCS);

    // Load trap assets
    this.load.aseprite(ASSET_KEYS.TRAP_FLAME, TRAP_FLAME_IMG, TRAP_FLAME_JSON);
    this.load.aseprite(ASSET_KEYS.TRAP_SPIKE, TRAP_SPIKE_IMG, TRAP_SPIKE_JSON);

    // Load NPC assets
    this.load.aseprite(ASSET_KEYS.BAT, BAT_IMG, BAT_JSON);
    this.load.aseprite(ASSET_KEYS.GHOST, GHOST_IMG, GHOST_JSON);
    this.load.aseprite(ASSET_KEYS.HAND, HAND_IMG, HAND_JSON);
    this.load.aseprite(ASSET_KEYS.MOUSE, MOUSE_IMG, MOUSE_JSON);
    this.load.aseprite(ASSET_KEYS.SLIME, SLIME_IMG, SLIME_JSON);

    // Load regi assets
    this.load.image(ASSET_KEYS.ELDER_DRIFTS_SECRET_DOOR, SECRET_DOOR);

    // Load animated objects assets
    this.load.aseprite(
      ASSET_KEYS.CANDLEFLAME,
      CANDLEFLAME_IMG,
      CANDLEFLAME_JSON,
    );

    this.load.json(ASSET_KEYS.READABLE_MESSAGES, CEMETERY_READABLES);
    this.load.aseprite(ASSET_KEYS.REGI_DOOR, REGI_DOOR_IMG, REGI_DOOR_JSON);
  }

  public create(): void {
    super.create();
    this.#createElderDriftsAnimations();
  }

  #createElderDriftsAnimations(): void {
    this.anims.createFromAseprite(ASSET_KEYS.TRAP_FLAME);
    this.anims.createFromAseprite(ASSET_KEYS.TRAP_SPIKE);
    this.anims.createFromAseprite(ASSET_KEYS.BAT);
    this.anims.createFromAseprite(ASSET_KEYS.GHOST);
    this.anims.createFromAseprite(ASSET_KEYS.HAND);
    this.anims.createFromAseprite(ASSET_KEYS.MOUSE);
    this.anims.createFromAseprite(ASSET_KEYS.SLIME);
    this.anims.createFromAseprite(ASSET_KEYS.CANDLEFLAME);
  }
}
