import { ElderDriftsGameScene } from "../scenes/elder-drifts-game-scene";
import { ElderDriftsPreloadScene } from "../scenes/elder-drifts-preload-scene";
import { GameOverScene } from "../scenes/game-over-scene";
import { SCENE_KEYS } from "../scenes/scene-keys";
import { UIScene } from "../scenes/ui-scene";
import type { SceneLoader } from "./types";

export const loadElderDriftsScenes: SceneLoader = (game) => {
  game.scene.add(
    SCENE_KEYS.ELDER_DRIFTS_PRELOAD_SCENE,
    ElderDriftsPreloadScene,
    false,
  );
  game.scene.add(
    SCENE_KEYS.ELDER_DRIFTS_GAME_SCENE,
    ElderDriftsGameScene,
    false,
  );
  game.scene.add(SCENE_KEYS.UI_SCENE, UIScene, false);
  game.scene.add(SCENE_KEYS.GAME_OVER_SCENE, GameOverScene, false);
  game.scene.start(SCENE_KEYS.ELDER_DRIFTS_PRELOAD_SCENE);
};
