import * as Phaser from "phaser";
import {
  ASSET_KEYS,
  ANIMATED_OBJECT_ANIMATION_KEYS,
} from "../../common/assets";
import { INTERACTIVE_OBJECT_TYPE } from "../../common/constants";
import { type TiledInteractiveCandleObject } from "../../common/tiled/types";
import { type CustomObject } from "../../common/types";
import { InteractiveObjectComponent } from "../../components/interactive-object-component";

export class InteractiveCandle
  extends Phaser.Physics.Arcade.Sprite
  implements CustomObject
{
  private _isOn: boolean;
  private _id: string;

  public constructor(
    scene: Phaser.Scene,
    config: TiledInteractiveCandleObject,
    onInteract?: () => void,
  ) {
    super(
      scene,
      config.x,
      config.y,
      ASSET_KEYS.CANDLEFLAME,
      "0", // Start with frame 0
    );

    this._id = config.id;
    this._isOn = false;

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true);
    this.setAlpha(0); // Start invisible (off state) but keep visible=true for interaction

    new InteractiveObjectComponent(this, INTERACTIVE_OBJECT_TYPE.AUTO, () => {
      this._isOn = !this._isOn;
      this.#updateCandleState();
      onInteract?.();
      return true;
    });

    this.disableObject();
  }

  public id(): string {
    return this._id;
  }

  public isOn(): boolean {
    return this._isOn;
  }

  enableObject(): void {
    this.active = true;
    this.visible = true; // Must be visible for proximity detection
    this.#updateCandleState();
  }

  disableObject(): void {
    this.active = false;
    this.visible = false;
  }

  #updateCandleState(): void {
    if (this._isOn) {
      this.setAlpha(1);
      if (!this.anims.isPlaying) {
        this.play({
          key: ANIMATED_OBJECT_ANIMATION_KEYS.CANDLEFLAME,
          repeat: -1,
        });
      }
    } else {
      this.anims.stop();
      this.setAlpha(0);
    }
  }
}
