import type * as Phaser from "phaser";
import { ASSET_KEYS, BIRD_TYPES } from "../common/assets";
import * as CONFIG from "../common/config";
import { DEATH_REASON, DIRECTION, STORY_FLAG } from "../common/constants";
import { CUSTOM_EVENTS, EVENT_BUS } from "../common/event-bus";
import { logger } from "../common/logger";
import { MusicCarryManager } from "../common/music-carry-manager";
import {
  TILED_LAYER_NAMES,
  TILED_TILESET_NAMES,
} from "../common/tiled/constants";
import {
  getAllLayerNamesWithPrefix,
  getTiledCandleObjectsFromMap,
  getTiledHidingPlaceObjectsFromMap,
  getTiledTrapObjectsFromMap,
} from "../common/tiled/utils";
import type { InteractiveGameObject } from "../common/types";
import { isPositionOnIce } from "../common/utils";
import type { NPC } from "../entities/npcs/npc";
import type { HideNPCData, TalkToPlayerData } from "../entities/npcs/npc-types";
import type { BaseTrap } from "../entities/objects/base-trap";
import { HidingPlace } from "../entities/objects/campground/hiding_place";
import { FlameTrap } from "../entities/objects/flame-trap";
import { InteractiveCandle } from "../entities/objects/interactive_candle";
import { SpikeTrap } from "../entities/objects/spike-trap";
import { createTrap } from "../entities/objects/trap";
import { BaseGameScene } from "./base-game-scene";
import { SCENE_KEYS } from "./scene-keys";

const REGI_ANSWER = [
  ["", ".", ".", ".", "", "."],
  ["", ".", ".", "", "", ""],
  ["", ".", ".", "", ".", ""],
  [".", ".", "", ".", "", ""],
  [".", "", "", ".", ".", ""],
  [".", ".", "", "", ".", ""],
];

export class ElderDriftsGameScene extends BaseGameScene {
  #iceLayer: Phaser.Tilemaps.TilemapLayer | null = null;
  #trapGroup!: Phaser.GameObjects.Group;
  #trapsByRoom = new Map<number, BaseTrap[]>();
  #candlesByRoom = new Map<number, InteractiveCandle[]>();
  #idToCandle = new Map<string, InteractiveCandle>();

  #trapTime = 0; // Global timer for trap animations (in ms)
  #musicCarryManager: MusicCarryManager;
  #hidingPlacesByRoom = new Map<number, HidingPlace[]>();
  #hidingPlacesGroup!: Phaser.GameObjects.Group;
  #hotColdTarget = { x: 200, y: 120 }; // Will be set from hiding places in room 1
  #lastHotColdDistance = Infinity;
  #hotColdClearTintTimer: Phaser.Time.TimerEvent | null = null;
  #isProcessingHotCold = false;
  #hasHotColdTarget = false;

  static readonly #MUSIC_CARRY_APPROACH_DISTANCE_PX = 64;
  static readonly #MUSIC_CARRY_EXIT_DISTANCE_PX = 64;
  static readonly #MUSIC_BAT_ROOM_ID = 15;

  constructor() {
    super(SCENE_KEYS.ELDER_DRIFTS_GAME_SCENE);
    this.#musicCarryManager = new MusicCarryManager({
      scene: this,
      birdType: BIRD_TYPES.BAT,
      allowedRoomId: ElderDriftsGameScene.#MUSIC_BAT_ROOM_ID,
      approachDistancePx:
        ElderDriftsGameScene.#MUSIC_CARRY_APPROACH_DISTANCE_PX,
      exitDistancePx: ElderDriftsGameScene.#MUSIC_CARRY_EXIT_DISTANCE_PX,
      showInvalidDropMarker: true,
      onInvalidDestination: () => {
        EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
          messages: ["I can't drop you there!"],
        });
      },
    });
  }

  protected override createLevel(): Phaser.Tilemaps.Tilemap | undefined {
    const map = super.createLevel();
    if (!map) {
      this.#iceLayer = null;
      return undefined;
    }

    // Create ice layer
    const collisionTiles = map.addTilesetImage(
      TILED_TILESET_NAMES.COLLISION,
      ASSET_KEYS.COLLISION,
    );

    if (!collisionTiles) {
      this.#iceLayer = null;
    } else {
      const iceLayer = map.createLayer(
        TILED_LAYER_NAMES.ICE,
        collisionTiles,
        0,
        0,
      );

      if (iceLayer) {
        this.#iceLayer = iceLayer;
        this.#iceLayer.setDepth(5).setAlpha(CONFIG.DEBUG_COLLISION_ALPHA);
        this.#iceLayer.setTint(0x0000aa);
      } else {
        this.#iceLayer = null;
      }
    }

    // Initialize trap group
    this.#trapGroup = this.add.group([]);
    this.#trapsByRoom.clear();

    // Initialize hiding places group
    this.#hidingPlacesGroup = this.add.group([]);
    this.#hidingPlacesByRoom.clear();

    // Process traps and hiding places from Tiled
    const rooms = getAllLayerNamesWithPrefix(map, TILED_LAYER_NAMES.ROOMS).map(
      (layerName: string) => ({
        name: layerName,
        roomId: parseInt(layerName.split("/")[1], 10),
      }),
    );

    const trapLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.TRAPS}`),
    );

    trapLayers.forEach((layer) => {
      const objects = getTiledTrapObjectsFromMap(map, layer.name);
      const traps: BaseTrap[] = [];
      objects.forEach((object) => {
        const trap = createTrap(this, object);
        this.#trapGroup.add(trap);
        traps.push(trap);
      });
      if (traps.length > 0) {
        this.#trapsByRoom.set(layer.roomId, traps);
      }
    });

    // Process hiding places
    const hidingPlaceLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.HIDING_PLACES}`),
    );

    hidingPlaceLayers.forEach((layer) => {
      const objects = getTiledHidingPlaceObjectsFromMap(map, layer.name);
      const hidingPlaces: HidingPlace[] = [];
      objects.forEach((object) => {
        const hidingPlace = new HidingPlace(this, object);
        this.#hidingPlacesGroup.add(hidingPlace);
        hidingPlaces.push(hidingPlace);
      });
      if (hidingPlaces.length > 0) {
        this.#hidingPlacesByRoom.set(layer.roomId, hidingPlaces);
      }
    });

    const candleLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.CANDLES}`),
    );

    candleLayers.forEach((layer) => {
      const objects = getTiledCandleObjectsFromMap(map, layer.name);
      const candles: InteractiveCandle[] = [];
      objects.forEach((object) => {
        const candle = new InteractiveCandle(this, object, () => {
          this.checkRegiWin();
        });
        this.#idToCandle.set(candle.id(), candle);
        candles.push(candle);
      });
      this.#candlesByRoom.set(layer.roomId, candles);
    });

    return map;
  }

  protected override enableRoomObjects(roomId: number): void {
    super.enableRoomObjects(roomId);
    this.#trapsByRoom.get(roomId)?.forEach((trap) => {
      trap.enableObject();
    });
    this.#hidingPlacesByRoom.get(roomId)?.forEach((hidingPlace) => {
      hidingPlace.enableObject();
    });

    this.#candlesByRoom.get(roomId)?.forEach((candle) => {
      candle.enableObject();
    });
  }

  protected override disableRoomObjects(roomId: number): void {
    super.disableRoomObjects(roomId);
    this.#trapsByRoom.get(roomId)?.forEach((trap) => {
      trap.disableObject();
    });
    this.#hidingPlacesByRoom.get(roomId)?.forEach((hidingPlace) => {
      hidingPlace.disableObject();
    });
    this.#candlesByRoom.get(roomId)?.forEach((candle) => {
      candle.disableObject();
    });
  }

  protected override appendRoomInteractiveObjects(
    roomId: number,
    objects: InteractiveGameObject[],
  ): void {
    this.#hidingPlacesByRoom.get(roomId)?.forEach((hidingPlace) => {
      objects.push(hidingPlace);
    });
    const candles = this.#candlesByRoom.get(roomId);
    candles?.forEach((candle) => {
      objects.push(candle);
    });
  }

  public override update(): void {
    super.update();

    // Update global trap timer
    this.#trapTime += this.game.loop.delta;

    // Update all traps with global time
    this.#trapGroup.children.entries.forEach((trap) => {
      (trap as BaseTrap).updateFromGlobalTime(this.#trapTime);
    });
  }

  protected override registerRoundColliders(): void {
    super.registerRoundColliders();

    // Collision detection for traps - kill player when active
    this.physics.add.overlap(
      this.playerObject,
      this.#trapGroup,
      (_player, trap) => {
        const trapObj = trap as BaseTrap;
        if (trapObj instanceof SpikeTrap && trapObj.isActive) {
          this.playerObject.setDeathReason(DEATH_REASON.SPIKE_TRAP);
          this.playerObject.hit(DIRECTION.DOWN, 1);
        } else if (trapObj instanceof FlameTrap && trapObj.isActive) {
          this.playerObject.setDeathReason(DEATH_REASON.FLAME_TRAP);
          this.playerObject.hit(DIRECTION.DOWN, 1);
        }
      },
    );
  }

  public isPlayerOnIce(): boolean {
    const player = this.playerObject;
    return isPositionOnIce(this.#iceLayer, player.x, player.y);
  }

  protected override registerRoundEvents(): void {
    super.registerRoundEvents();
    this.#musicCarryManager.registerEvents();
    EVENT_BUS.on(CUSTOM_EVENTS.HOT_COLD_SONG, this.#handleHotColdSong, this);
    EVENT_BUS.on(
      CUSTOM_EVENTS.DIALOG_COMPLETE,
      this.#clearInvalidDropMarker,
      this,
    );
    EVENT_BUS.on(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
    this.onEnterRoom(this.currentRoomId);
  }

  protected override unregisterRoundEvents(): void {
    super.unregisterRoundEvents();
    this.#musicCarryManager.unregisterEvents();
    EVENT_BUS.off(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
    EVENT_BUS.off(CUSTOM_EVENTS.HOT_COLD_SONG, this.#handleHotColdSong, this);
    EVENT_BUS.off(
      CUSTOM_EVENTS.DIALOG_COMPLETE,
      this.#clearInvalidDropMarker,
      this,
    );
  }

  private onEnterRoom = (roomId: number): void => {
    const camera = this.cameras.main;
    camera.postFX.clear();

    if (roomId === 1) {
      const colorMatrix =
        camera.postFX.addColorMatrix() as Phaser.Display.ColorMatrix;
      colorMatrix.saturate(-1); // Fully desaturate
      colorMatrix.saturate(0.4);
      colorMatrix.contrast(0.12);

      const matrix = colorMatrix.getData();
      matrix[0] *= 1.0;
      matrix[6] *= 0.9;
      matrix[12] *= 0.75;

      matrix[4] += 8;
      matrix[9] += 2;

      colorMatrix.set(matrix);

      camera.postFX.addGlow(0x221133, 1.5, 0.15, false, 0.05, 8);
    }
  };

  #clearInvalidDropMarker = (): void => {
    this.#musicCarryManager.clearInvalidDropMarker();
  };

  protected override getHidingPlaceByIdentifier(
    identifier: string,
  ): HidingPlace | null | undefined {
    // Search all rooms for the hiding place
    for (const hidingPlaces of this.#hidingPlacesByRoom.values()) {
      const hidingPlace = hidingPlaces.find(
        (hp) => hp.identifier === identifier,
      );
      if (hidingPlace) {
        return hidingPlace;
      }
    }
    return null;
  }

  protected override handleHideNPC(data: HideNPCData): Promise<void> {
    return new Promise((resolve) => {
      logger.event("HIDE_NPC event:", data);
      const npc = this.getCharacterByIdentifier(data.identifier) as NPC;
      const hidingPlace = this.getHidingPlaceByIdentifier(data.hidingPlace);

      if (npc === undefined) {
        console.error(`NPC not found for identifier: ${data.identifier}`);
        resolve();
        return;
      }

      if (hidingPlace === undefined || hidingPlace === null) {
        console.error(
          `Hiding place not found for identifier: ${data.hidingPlace}`,
        );
        resolve();
        return;
      }

      // Hide the NPC
      npc.hideInHidingPlace(hidingPlace);

      // If this is the ghost, ensure position is set correctly after hiding
      const yOffset = data.identifier === "GHOST" ? -32 : 0;
      if (yOffset !== 0) {
        // Position ghost at the center of the hiding place (horizontally) and slightly above (vertically)
        npc.setPosition(
          hidingPlace.x + hidingPlace.width / 2,
          hidingPlace.y + yOffset,
        );
      }

      // Set hot/cold target to the hiding place's center (with offset for ghost)
      this.#hotColdTarget = {
        x: hidingPlace.x + hidingPlace.width / 2,
        y: hidingPlace.y + hidingPlace.height / 2 + yOffset,
      };
      this.#hasHotColdTarget = true;

      resolve();
    });
  }

  protected override async handleTalkToPlayer(
    data: TalkToPlayerData,
  ): Promise<number | undefined> {
    const next = await super.handleTalkToPlayer(data);

    // If we just talked to the ghost, clear the hot/cold target so the next song shows neutral
    if (data.identifier === "GHOST") {
      this.#hasHotColdTarget = false;
      this.#lastHotColdDistance = Infinity;
    }

    return next;
  }

  protected override applyRoundGameworldState(currentLevel: string): void {
    super.applyRoundGameworldState(currentLevel);

    const dm = this.dataManager;
    const ghost00 = dm.getFlagValue("ghost00");
    if (ghost00 !== "completed") {
      this.#hasHotColdTarget = false;
      this.#lastHotColdDistance = Infinity;
      return;
    }

    const ghost01 = dm.getFlagValue("ghost01");
    const ghost02 = dm.getFlagValue("ghost02");
    const ghost03 = dm.getFlagValue("ghost03");

    let targetHiding = "ghost01";
    if (ghost02 === "completed") {
      targetHiding = "ghost03";
    } else if (ghost01 === "completed") {
      targetHiding = "ghost02";
    }

    // Use existing hide handler to place ghost and set hot/cold target
    if (ghost03 !== "completed") {
      void this.handleHideNPC({
        identifier: "GHOST",
        hidingPlace: targetHiding,
      });
      dm.setFlagValue(targetHiding, "hiding");
    }
  }

  #handleHotColdSong = (): void => {
    // Prevent multiple simultaneous triggers
    if (this.#isProcessingHotCold) {
      return;
    }
    this.#isProcessingHotCold = true;

    // If we don't have an active hiding target, show a message and exit
    if (!this.#hasHotColdTarget) {
      EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
        messages: ["Nothing happened."],
      });
      this.#isProcessingHotCold = false;
      return;
    }

    const player = this.playerObject;
    const dx = player.x - this.#hotColdTarget.x;
    const dy = player.y - this.#hotColdTarget.y;
    const currentDistance = Math.hypot(dx, dy);

    const wasDistance = this.#lastHotColdDistance;
    this.#lastHotColdDistance = currentDistance;

    // Clear any existing timer
    if (this.#hotColdClearTintTimer) {
      this.#hotColdClearTintTimer.destroy();
      this.#hotColdClearTintTimer = null;
    }

    let tint = 0xffffff;
    if (currentDistance < wasDistance) {
      tint = 0xdd6666; // hotter (closer) - red
    } else if (currentDistance > wasDistance) {
      tint = 0x6666dd; // colder (farther) - blue
    }

    // Tint the player sprite immediately
    this.playerObject.setTint(tint);

    // Clear tint after 1 second using a timer instead of tween
    this.#hotColdClearTintTimer = this.time.delayedCall(500, () => {
      this.playerObject.clearTint();
      this.#hotColdClearTintTimer = null;
      this.#isProcessingHotCold = false;
    });
  };

  private checkRegiWin(): void {
    let won = true;
    this.#idToCandle.forEach((candle, id) => {
      const charIndex = Number(id[0]) - 1;
      const dotIndex = Number(id[1]) - 1;
      if (
        (REGI_ANSWER[charIndex][dotIndex] === "." && !candle.isOn()) ||
        (REGI_ANSWER[charIndex][dotIndex] === "" && candle.isOn())
      ) {
        won = false;
      }
    });

    if (!won) {
      return;
    }

    const flag = STORY_FLAG.cemetery13;
    this.dataManager.setFlagToCompleted(flag);
    this.dataManager.completeInteraction(flag);
    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: ["A secret door appeared!"],
      choices: [],
    });
  }
}
