import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import GameworldZoneClient from "../../../components/overworld/GameworldZoneClient";
import { loadElderDriftsScenes } from "../gameworld/scene-loaders/elder-drifts";
import ElderDriftsBody from "./ElderDriftsBody";
import { type ElderDriftsState } from "./types";

const ElderDriftsManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: ElderDriftsState;
  initialTeamState: TeamHuntState;
}) => {
  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GameworldZoneClient
        roundSlug="elder_drifts"
        initialState={initialState}
        initialTeamState={initialTeamState}
        sceneLoader={loadElderDriftsScenes}
        render={({ state, teamState, gameNode }) => {
          return (
            <ElderDriftsBody
              state={state}
              teamState={teamState}
              gameNode={gameNode}
            />
          );
        }}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("elder_drifts-root");
if (elem) {
  const { initialElderDriftsState: state, initialTeamState } =
    window as unknown as {
      initialElderDriftsState: ElderDriftsState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <ElderDriftsManager
      initialState={state}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount ElderDriftsManager because #elder_drifts-root was nowhere to be found",
  );
}
