import type * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import type { TiledTrapObject } from "../../common/tiled/types";
import { BaseTrap } from "./base-trap";

/**
 * Spike trap that animates up and down, causing damage when spikes are up.
 */
export class SpikeTrap extends BaseTrap {
  // Pattern constants for patterns 40+
  private static readonly P40_OFFSET_STEP = 400; // Offset between consecutive patterns (41, 42, 43, 44)
  private static readonly P40_BASE = 41; // First pattern number that uses offset (pattern 41)

  // Frame indices
  private static readonly FRAME_INACTIVE = 0;
  private static readonly FRAME_ACTIVE = 4;
  private static readonly FRAME_TRANSITION_UP_START = 1;
  private static readonly FRAME_TRANSITION_UP_END = 3;
  private static readonly FRAME_TRANSITION_DOWN_START = 5;
  private static readonly FRAME_TRANSITION_DOWN_END = 7;

  // Hitbox constants (12x12 centered in bottom 16x16 of 16x24 sprite)
  private static readonly HITBOX_SIZE = 12;
  private static readonly HITBOX_OFFSET_X = 2;
  private static readonly HITBOX_OFFSET_Y = 10;

  #isActive = false; // Whether spikes are currently up (dangerous)
  readonly #inactiveTime = 2000; // 2 second hold time for inactive state
  readonly #activeTime = 1200; // 1.5 second hold time for active state
  private static readonly TRANSITION_TIME = 300; // 100ms per frame for 3 frames
  private static readonly NUM_TRANSITION_FRAMES = 3;

  constructor(scene: Phaser.Scene, config: TiledTrapObject) {
    super(scene, config, ASSET_KEYS.TRAP_SPIKE);

    // Set hitbox to 12x12, centered in the bottom 16x16 of the sprite (16x24)
    if (this.body) {
      this.body.setSize(SpikeTrap.HITBOX_SIZE, SpikeTrap.HITBOX_SIZE, false);
      this.body.setOffset(SpikeTrap.HITBOX_OFFSET_X, SpikeTrap.HITBOX_OFFSET_Y);
    }
  }

  /**
   * Override to use the extended cycle time (includes transition periods).
   * Total cycle: inactiveTime + activeTime + 600ms (300ms per transition)
   */
  public updateFromGlobalTime(globalTime: number): void {
    if (!this.active || !this.visible) {
      return;
    }

    // Pattern -1: permanently up (always active)
    if (this.pattern === -1) {
      const wasActive = this.#isActive;
      this.#isActive = true;
      this.setFrame(SpikeTrap.FRAME_ACTIVE);
      if (wasActive !== this.#isActive && this.body) {
        this.body.enable = true;
      }
      return;
    }

    const totalCycleTime = this.#getTotalCycleTime();
    let offset = 0;

    // Adjust offset based on pattern
    // Pattern 1: offset so its inactive phase is centered around pattern 0's active phase
    // This ensures pattern 0 and pattern 1 are never both active at the same time
    if (this.pattern === 1) {
      // Pattern 0 active phase center: inactiveTime + transitionTime + activeTime/2
      // Pattern 1 inactive phase center: inactiveTime/2
      // Offset to align centers: (inactiveTime + transitionTime + activeTime/2) - inactiveTime/2
      const pattern0ActiveCenter =
        this.#inactiveTime + SpikeTrap.TRANSITION_TIME + this.#activeTime / 2;
      const pattern1InactiveCenter = this.#inactiveTime / 2;
      offset = pattern0ActiveCenter - pattern1InactiveCenter;
    }

    // Patterns 41-44: 41 starts 400ms after 0, 42 starts 400ms after 41, etc.
    if (this.pattern >= SpikeTrap.P40_BASE) {
      const patternOffset =
        (this.pattern - SpikeTrap.P40_BASE) * SpikeTrap.P40_OFFSET_STEP;
      offset = patternOffset;
    }

    // Calculate current phase in extended cycle (0-1)
    const adjustedTime = (globalTime + offset) % totalCycleTime;
    const phase = adjustedTime / totalCycleTime;

    this.onUpdate(phase);
  }

  /**
   * Calculates the total cycle time including transitions.
   */
  #getTotalCycleTime(): number {
    return (
      this.#inactiveTime + this.#activeTime + SpikeTrap.TRANSITION_TIME * 2
    );
  }

  protected onUpdate(phase: number): void {
    // Timing breakdown (phase is 0-1 over total cycle):
    // - Frame 0 (inactive): hold for inactiveTime
    // - Frames 1-3 (transition up): TRANSITION_TIME total
    // - Frame 4 (active): hold for activeTime
    // - Frames 5-7 (transition down): TRANSITION_TIME total
    const totalCycleTime = this.#getTotalCycleTime();
    const currentTime = phase * totalCycleTime;
    const inactiveTime = this.#inactiveTime;
    const activeTime = this.#activeTime;
    const transitionTime = SpikeTrap.TRANSITION_TIME;

    const { frameIndex, isActive } = this.#calculateFrameAndState(
      currentTime,
      inactiveTime,
      activeTime,
      transitionTime,
    );

    const wasActive = this.#isActive;
    this.#isActive = isActive;

    this.setFrame(frameIndex);

    // Enable/disable physics only when state changes (performance optimization)
    if (wasActive !== this.#isActive && this.body) {
      this.body.enable = this.#isActive;
    }
  }

  /**
   * Calculates the current frame index and active state based on time in cycle.
   */
  #calculateFrameAndState(
    currentTime: number,
    inactiveTime: number,
    activeTime: number,
    transitionTime: number,
  ): { frameIndex: number; isActive: boolean } {
    if (currentTime < inactiveTime) {
      // Inactive hold
      return {
        frameIndex: SpikeTrap.FRAME_INACTIVE,
        isActive: false,
      };
    }

    if (currentTime < inactiveTime + transitionTime) {
      // Transition up (frames 1-3)
      const transitionPhase = (currentTime - inactiveTime) / transitionTime;
      const frameIndex =
        SpikeTrap.FRAME_TRANSITION_UP_START +
        Math.floor(transitionPhase * SpikeTrap.NUM_TRANSITION_FRAMES);
      return {
        frameIndex: Math.min(frameIndex, SpikeTrap.FRAME_TRANSITION_UP_END),
        isActive: frameIndex >= SpikeTrap.FRAME_TRANSITION_UP_END,
      };
    }

    if (currentTime < inactiveTime + transitionTime + activeTime) {
      // Active hold
      return {
        frameIndex: SpikeTrap.FRAME_ACTIVE,
        isActive: true,
      };
    }

    // Transition down (frames 5-7)
    const transitionPhase =
      (currentTime - inactiveTime - transitionTime - activeTime) /
      transitionTime;
    const frameIndex =
      SpikeTrap.FRAME_TRANSITION_DOWN_START +
      Math.floor(transitionPhase * SpikeTrap.NUM_TRANSITION_FRAMES);
    return {
      frameIndex: Math.min(frameIndex, SpikeTrap.FRAME_TRANSITION_DOWN_END),
      isActive: frameIndex < SpikeTrap.FRAME_TRANSITION_DOWN_END,
    };
  }

  get cycleTime(): number {
    // Return the average cycle time for compatibility with BaseTrap
    return (this.#inactiveTime + this.#activeTime) / 2;
  }

  get isActive(): boolean {
    return this.#isActive;
  }
}
