import type * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import { DIRECTION } from "../../common/constants";
import type { TiledTrapObject } from "../../common/tiled/types";
import type { Direction } from "../../common/types";
import { BaseTrap } from "./base-trap";

/**
 * Flame trap that shoots flames in a direction, causing damage when active.
 * Frame 0 is inactive, frames 1-8 show the flame growing.
 */
export class FlameTrap extends BaseTrap {
  // Frame indices
  private static readonly FRAME_INACTIVE = 0;
  private static readonly FRAME_ACTIVE_START = 1;
  private static readonly NUM_ACTIVE_FRAMES = 8;

  // Timing constants
  private static readonly TRANSITION_TIME = 800; // Time to animate through all active frames (frames 1-8)
  readonly #inactiveTime = 1100; // 2 second hold time for inactive state (frame 0)

  // Pattern constants for patterns 40+
  private static readonly P40_OFFSET_STEP = 400; // Offset between consecutive patterns (41, 42, 43, 44)
  private static readonly P40_BASE = 41; // First pattern number that uses offset (pattern 41)

  // ============================================================================
  // Hitbox base constants
  // ============================================================================
  // Flame is ~16px tall, centered in 32px sprite (offset_y = 4px)
  // Exclude 20px on left and right (offset_x = 20px, width = frame_width - 40px)
  private static readonly HITBOX_HEIGHT = 16;
  private static readonly HITBOX_SIDE_MARGIN = 20; // Exclude 20px on each side

  // ============================================================================
  // Sprite positioning constants
  // ============================================================================
  private static readonly SPRITE_SHIFT = 32; // Amount to shift sprites for UP/DOWN/LEFT directions

  // ============================================================================
  // Hitbox offset constants by direction
  // ============================================================================
  // RIGHT direction (default orientation)
  private static readonly RIGHT_HITBOX_OFFSET_X = 16; // HITBOX_SIDE_MARGIN
  private static readonly RIGHT_HITBOX_OFFSET_Y = 8; // HITBOX_OFFSET_Y

  // LEFT direction (flipped horizontally, origin at right edge)
  private static readonly LEFT_HITBOX_OFFSET_X = 16; // Position from right edge (nozzle), adjusted for sprite shift
  private static readonly LEFT_HITBOX_OFFSET_Y = 8; // HITBOX_OFFSET_Y

  // UP direction (rotated -90°, origin at bottom-left)
  // With origin at (0, 1), the hitbox grows upward from a fixed base point
  private static readonly UP_HITBOX_OFFSET_X = -24; // Position from left edge
  private static readonly UP_HITBOX_OFFSET_Y = 16; // Base position - hitbox grows upward from here

  // DOWN direction (rotated 90°, origin at top-left)
  // offset_x depends on hitboxHeight (calculated dynamically), offset_y is constant
  private static readonly DOWN_HITBOX_OFFSET_X_BASE = -24; // FRAME_HEIGHT - HITBOX_OFFSET_Y
  private static readonly DOWN_HITBOX_OFFSET_Y = 16; // Adjusted for sprite shift

  // Frame widths (for dynamic hitbox calculation)
  private static readonly FRAME_WIDTHS = [
    33, // Frame 0: inactive
    36, // Frame 1
    40, // Frame 2
    48, // Frame 3
    64, // Frame 4
    80, // Frame 5
    96, // Frame 6
    96, // Frame 7
    33, // Frame 8: inactive
  ] as const;

  #isActive = false; // Whether flame is currently active (dangerous)
  #currentFrame = 0;

  constructor(scene: Phaser.Scene, config: TiledTrapObject) {
    super(scene, config, ASSET_KEYS.TRAP_FLAME);

    // Apply direction-based rotation/flipping
    const direction = config.direction ?? DIRECTION.RIGHT;
    this.#applyDirection(direction);

    // Set initial hitbox (will be updated as frame changes)
    this.#updateHitbox(FlameTrap.FRAME_INACTIVE);
  }

  /**
   * Applies rotation/flipping based on direction.
   * Base frames point RIGHT.
   */
  #applyDirection(direction: Direction): void {
    switch (direction) {
      case DIRECTION.RIGHT:
        // Default, no transformation needed
        this.setOrigin(0, 0);
        break;
      case DIRECTION.LEFT:
        // Set origin to right edge (1, 0) so flipping happens around the nozzle
        this.setFlipX(true);
        this.setOrigin(1, 0);
        this.#applySpriteShift();
        break;
      case DIRECTION.UP:
        // Rotate -90 degrees (counter-clockwise) to point UP
        // Set origin to bottom-left (0, 1) so it rotates around the base
        this.setAngle(-90);
        this.setOrigin(0, 1);
        this.#applySpriteShift();
        this.y += FlameTrap.SPRITE_SHIFT;
        break;
      case DIRECTION.DOWN:
        // Rotate 90 degrees (clockwise) to point DOWN
        this.setAngle(90);
        this.setOrigin(0, 0);
        this.#applySpriteShift();
        break;
    }
  }

  /**
   * Shifts sprite position for rotated/flipped directions.
   */
  #applySpriteShift(): void {
    this.x += FlameTrap.SPRITE_SHIFT;
  }

  /**
   * Updates the hitbox based on the current frame.
   * Hitbox is 24px tall (centered) and excludes 16px on each side.
   * When sprite is rotated, Phaser rotates the body too, so we need to account for that.
   */
  #updateHitbox(frameIndex: number): void {
    if (!this.body) {
      return;
    }

    const frameWidth = FlameTrap.FRAME_WIDTHS[frameIndex] ?? 32;

    // Calculate hitbox dimensions (always in sprite's local coordinate system)
    const hitboxWidth = frameWidth - FlameTrap.HITBOX_SIDE_MARGIN * 2;
    const hitboxHeight = FlameTrap.HITBOX_HEIGHT; // 24px

    const direction = this.direction ?? DIRECTION.RIGHT;

    switch (direction) {
      case DIRECTION.RIGHT:
        this.body.setSize(hitboxWidth, hitboxHeight, false);
        this.body.setOffset(
          FlameTrap.RIGHT_HITBOX_OFFSET_X,
          FlameTrap.RIGHT_HITBOX_OFFSET_Y,
        );
        break;

      case DIRECTION.LEFT:
        this.body.setSize(hitboxWidth, hitboxHeight, false);
        this.body.setOffset(
          FlameTrap.LEFT_HITBOX_OFFSET_X,
          FlameTrap.LEFT_HITBOX_OFFSET_Y,
        );
        break;

      case DIRECTION.UP:
        // Swap dimensions for rotation: width becomes height, height becomes width
        this.body.setSize(hitboxHeight, hitboxWidth, false);
        // offset_y adjusts as flame grows to keep base anchored
        this.body.setOffset(
          FlameTrap.UP_HITBOX_OFFSET_X,
          FlameTrap.UP_HITBOX_OFFSET_Y - hitboxWidth,
        );
        break;

      case DIRECTION.DOWN:
        // Swap dimensions for rotation: width becomes height, height becomes width
        this.body.setSize(hitboxHeight, hitboxWidth, false);
        this.body.setOffset(
          FlameTrap.DOWN_HITBOX_OFFSET_X_BASE,
          FlameTrap.DOWN_HITBOX_OFFSET_Y,
        );
        break;
    }
  }

  /**
   * Override to use the extended cycle time (includes transition periods).
   * Total cycle: inactiveTime + transitionTime
   */
  public updateFromGlobalTime(globalTime: number): void {
    if (!this.active || !this.visible) {
      return;
    }

    const totalCycleTime = this.#getTotalCycleTime();

    // Calculate offset based on pattern
    // Patterns 41-44: 41 starts 400ms after 0, 42 starts 400ms after 41, etc.
    let offset = 0;
    if (this.pattern >= FlameTrap.P40_BASE) {
      const patternOffset =
        (this.pattern - FlameTrap.P40_BASE) * FlameTrap.P40_OFFSET_STEP;
      offset = patternOffset;
    }

    // Calculate current phase in extended cycle (0-1)
    const adjustedTime = (globalTime + offset) % totalCycleTime;
    const phase = adjustedTime / totalCycleTime;

    this.onUpdate(phase);
  }

  /**
   * Calculates the total cycle time.
   * Cycle: inactive (frame 0) → growth (frames 1-8) → back to inactive
   */
  #getTotalCycleTime(): number {
    return this.#inactiveTime + FlameTrap.TRANSITION_TIME;
  }

  protected onUpdate(phase: number): void {
    // Timing breakdown (phase is 0-1 over total cycle):
    // - Frame 0 (inactive): hold for inactiveTime
    // - Frames 1-8 (growth): TRANSITION_TIME total, then loop back to frame 0
    const totalCycleTime = this.#getTotalCycleTime();
    const currentTime = phase * totalCycleTime;
    const inactiveTime = this.#inactiveTime;
    const transitionTime = FlameTrap.TRANSITION_TIME;

    const { frameIndex, isActive } = this.#calculateFrameAndState(
      currentTime,
      inactiveTime,
      transitionTime,
    );

    const wasActive = this.#isActive;
    this.#isActive = isActive;

    // Update frame and hitbox if frame changed
    if (this.#currentFrame !== frameIndex) {
      this.#currentFrame = frameIndex;
      this.setFrame(frameIndex);
      this.#updateHitbox(frameIndex);
    }

    // Enable/disable physics only when state changes (performance optimization)
    if (wasActive !== this.#isActive && this.body) {
      this.body.enable = this.#isActive;
    }
  }

  /**
   * Calculates the current frame index and active state based on time in cycle.
   */
  #calculateFrameAndState(
    currentTime: number,
    inactiveTime: number,
    transitionTime: number,
  ): { frameIndex: number; isActive: boolean } {
    // currentTime is already modulo'd in updateFromGlobalTime, so it's in [0, totalCycleTime)
    const totalCycle = inactiveTime + transitionTime;

    // Use modulo to ensure we're always in valid range
    const wrappedTime = currentTime % totalCycle;

    if (wrappedTime < inactiveTime) {
      // Inactive hold (frame 0)
      return {
        frameIndex: FlameTrap.FRAME_INACTIVE,
        isActive: false,
      };
    }

    // Growth phase (frames 1-8)
    // After inactiveTime, animate through frames 1-8, then loop back to frame 0
    const transitionPhase = (wrappedTime - inactiveTime) / transitionTime;
    // Map phase (0-1) to frames 1-8 (8 frames total)
    // Clamp to ensure we don't exceed FRAME_ACTIVE_END
    const frameIndex =
      FlameTrap.FRAME_ACTIVE_START +
      Math.min(
        Math.floor(transitionPhase * FlameTrap.NUM_ACTIVE_FRAMES),
        FlameTrap.NUM_ACTIVE_FRAMES - 1,
      );
    return {
      frameIndex,
      isActive: true, // Flame is dangerous during growth
    };
  }

  get cycleTime(): number {
    // Return the total cycle time for compatibility with BaseTrap
    return this.#inactiveTime + FlameTrap.TRANSITION_TIME;
  }

  get isActive(): boolean {
    return this.#isActive;
  }
}
