import type * as Phaser from "phaser";
import type { TiledTrapObject } from "../../common/tiled/types";
import type { BaseTrap } from "./base-trap";
import { FlameTrap } from "./flame-trap";
import { SpikeTrap } from "./spike-trap";

/**
 * Factory function to create the appropriate trap type based on Tiled config.
 */
export function createTrap(
  scene: Phaser.Scene,
  config: TiledTrapObject,
): BaseTrap {
  switch (config.trapType) {
    case "FLAME":
      return new FlameTrap(scene, config);
    case "SPIKE":
      return new SpikeTrap(scene, config);
    default:
      throw new Error(`Unknown trap type: ${config.trapType}`);
  }
}
