import * as Phaser from "phaser";
import type { TiledTrapObject } from "../../common/tiled/types";
import type { CustomObject, Direction } from "../../common/types";

/**
 * Base class for floor traps that animate using a shared global timer.
 * This allows many traps to animate efficiently without individual tweens.
 */
export abstract class BaseTrap
  extends Phaser.Physics.Arcade.Sprite
  implements CustomObject
{
  #offset: number; // Phase offset in ms for staggered animations
  #direction?: Direction; // Direction for directional traps (e.g., flame traps)
  #pattern: number; // Pattern type (default: 0)

  constructor(scene: Phaser.Scene, config: TiledTrapObject, assetKey: string) {
    super(scene, config.x, config.y, assetKey, 0);

    this.#direction = config.direction;
    this.#offset = 0; // Offset is no longer configurable, use pattern instead
    this.#pattern = config.pattern ?? 0;

    scene.add.existing(this);
    scene.physics.add.existing(this);

    this.setOrigin(0, 0);
    this.setImmovable(true);
    if (this.body) {
      this.body.enable = false; // Start with physics disabled
    }

    // Initially disabled
    this.disableObject();
  }

  /**
   * Updates the trap animation frame based on global time.
   * This is called from the scene's update loop for all traps at once.
   * @param globalTime - Global time in ms (shared across all traps)
   */
  public updateFromGlobalTime(globalTime: number): void {
    if (!this.active || !this.visible) {
      return;
    }

    // Calculate current phase in cycle (0-1)
    const adjustedTime = (globalTime + this.#offset) % this.cycleTime;
    const phase = adjustedTime / this.cycleTime;

    // Let subclasses handle their specific update logic
    this.onUpdate(phase);
  }

  /**
   * Called by updateFromGlobalTime with the current phase (0-1).
   * Subclasses should override this to implement trap-specific behavior.
   * @param phase - Current phase in the cycle (0-1)
   */
  protected abstract onUpdate(phase: number): void;

  /**
   * Cycle time in ms. Each trap type defines its own cycle time.
   */
  abstract get cycleTime(): number;

  get direction(): Direction | undefined {
    return this.#direction;
  }

  get pattern(): number {
    return this.#pattern;
  }

  public disableObject(): void {
    if (this.body) {
      this.body.enable = false;
    }
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    this.active = true;
    this.visible = true;
    // Physics will be enabled/disabled by subclasses based on their behavior
  }
}
